style.css:
@-moz-document domain("youtube.com") {
/* --- 1. THE RGB KEYFRAMES --- */
    @keyframes rgb-cycle {
        0% { filter: hue-rotate(0deg); }
        100% { filter: hue-rotate(360deg); }
    }

    /* --- 2. THE PROGRESS BAR --- */
    .ytp-play-progress {
        background: #ff0000 !important; /* Base color for hue-rotate */
        animation: rgb-cycle 3s linear infinite !important;
        box-shadow: 0 0 10px rgba(255, 0, 0, 0.5) !important;
    }

    /* --- 3. THE LITTLE BALL (Scrubber) --- */
    /* This targets the actual ball and the color it inherits */
    .ytp-scrubber-button, 
    .ytp-swatch-background-color {
        background-color: #ff0000 !important;
        animation: rgb-cycle 3s linear infinite !important;
        border: none !important;
    }

    /* Adds a glow to the ball so it matches your thumbnail */
    .ytp-scrubber-button {
        box-shadow: 0 0 15px #ff0000 !important;
    }

    /* --- 4. HOVER EFFECT --- */
    /* Makes the ball pulse/glow more when you hover over the player */
    .ytp-chrome-bottom:hover .ytp-scrubber-button {
        transform: scale(1.2);
        box-shadow: 0 0 20px #ff0000 !important;
    }
}
